-- Learning insights (question->video minute, lecture notes, student challenges).
--
-- NOT required to run by hand: the migration 20261028120000_AddLearningInsights applies the
-- same idempotent statements automatically on server start. Use this script only if you
-- apply schema changes manually. Safe to run more than once. (PostgreSQL / Npgsql)

CREATE TABLE IF NOT EXISTS "QuestionExplanations" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "SourceType" character varying(30) NOT NULL,
  "QuestionId" integer NOT NULL,
  "LectureId" integer NOT NULL,
  "StartSeconds" integer NOT NULL,
  "EndSeconds" integer NULL,
  "Note" character varying(300) NULL,
  "OpenCount" integer NOT NULL DEFAULT 0,
  "CreatedAt" timestamp with time zone NOT NULL,
  "UpdatedAt" timestamp with time zone NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_QuestionExplanations_TeacherId_SourceType_QuestionId" ON "QuestionExplanations" ("TeacherId","SourceType","QuestionId");
CREATE INDEX IF NOT EXISTS "IX_QuestionExplanations_LectureId" ON "QuestionExplanations" ("LectureId");

CREATE TABLE IF NOT EXISTS "LectureNotes" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "StudentId" integer NOT NULL,
  "LectureId" integer NOT NULL,
  "Seconds" integer NOT NULL,
  "Body" character varying(1000) NOT NULL,
  "IsStarred" boolean NOT NULL DEFAULT false,
  "CreatedAt" timestamp with time zone NOT NULL,
  "UpdatedAt" timestamp with time zone NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_LectureNotes_StudentId_LectureId" ON "LectureNotes" ("StudentId","LectureId");

CREATE TABLE IF NOT EXISTS "StudentChallenges" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "ChallengerId" integer NOT NULL,
  "OpponentId" integer NOT NULL,
  "UnitId" integer NULL,
  "LessonId" integer NULL,
  "Difficulty" character varying(10) NULL,
  "QuestionIdsCsv" text NOT NULL,
  "TotalMarks" integer NOT NULL,
  "Status" character varying(20) NOT NULL,
  "CreatedAt" timestamp with time zone NOT NULL,
  "ExpiresAt" timestamp with time zone NOT NULL,
  "AcceptedAt" timestamp with time zone NULL,
  "PlayUntil" timestamp with time zone NULL,
  "ChallengerStartedAt" timestamp with time zone NULL,
  "ChallengerFinishedAt" timestamp with time zone NULL,
  "ChallengerScore" integer NULL,
  "ChallengerSeconds" integer NULL,
  "OpponentStartedAt" timestamp with time zone NULL,
  "OpponentFinishedAt" timestamp with time zone NULL,
  "OpponentScore" integer NULL,
  "OpponentSeconds" integer NULL,
  "WinnerId" integer NULL,
  "CompletedAt" timestamp with time zone NULL
);
CREATE INDEX IF NOT EXISTS "IX_StudentChallenges_TeacherId_ChallengerId" ON "StudentChallenges" ("TeacherId","ChallengerId");
CREATE INDEX IF NOT EXISTS "IX_StudentChallenges_TeacherId_OpponentId" ON "StudentChallenges" ("TeacherId","OpponentId");
CREATE INDEX IF NOT EXISTS "IX_StudentChallenges_TeacherId_Status" ON "StudentChallenges" ("TeacherId","Status");
